import { useState, useEffect } from 'react';
import type { City } from './cities';

export interface HourlyWeather {
  time: string[];
  temperature_2m: number[];
  apparent_temperature: number[];
  precipitation_probability: number[];
  windspeed_10m: number[];
}

export interface HourlyAirQuality {
  time: string[];
  european_aqi: number[];
  pm2_5: number[];
  pm10: number[];
}

export interface CitySnapshot {
  currentTemp: number;
  apparentTemp: number;
  currentAqi: number;
  currentWind: number;
  precipProb: number;
}

export interface CityData {
  snapshot: CitySnapshot | null;
  weather: HourlyWeather | null;
  airQuality: HourlyAirQuality | null;
  loading: boolean;
  error: string | null;
}

function currentHourIndex(times: string[]): number {
  const now = new Date();
  const nowStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}T${String(now.getHours()).padStart(2, '0')}:00`;
  const idx = times.indexOf(nowStr);
  return idx >= 0 ? idx : Math.min(times.length - 1, 12);
}

export function useCityData(city: City): CityData {
  const [data, setData] = useState<CityData>({ snapshot: null, weather: null, airQuality: null, loading: true, error: null });

  useEffect(() => {
    let cancelled = false;
    setData({ snapshot: null, weather: null, airQuality: null, loading: true, error: null });

    const weatherUrl =
      `https://api.open-meteo.com/v1/forecast?latitude=${city.lat}&longitude=${city.lon}` +
      `&hourly=temperature_2m,apparent_temperature,precipitation_probability,windspeed_10m` +
      `&forecast_days=1&timezone=${encodeURIComponent(city.timezone)}`;

    const aqUrl =
      `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${city.lat}&longitude=${city.lon}` +
      `&hourly=european_aqi,pm2_5,pm10&timezone=${encodeURIComponent(city.timezone)}&forecast_days=1`;

    Promise.all([fetch(weatherUrl).then((r) => r.json()), fetch(aqUrl).then((r) => r.json())])
      .then(([weatherJson, aqJson]) => {
        if (cancelled) return;
        const weather: HourlyWeather = weatherJson.hourly;
        const airQuality: HourlyAirQuality = aqJson.hourly;
        const idx = currentHourIndex(weather.time);
        const snapshot: CitySnapshot = {
          currentTemp: Math.round(weather.temperature_2m[idx]),
          apparentTemp: Math.round(weather.apparent_temperature[idx]),
          currentAqi: Math.round(airQuality.european_aqi[idx] ?? 0),
          currentWind: Math.round(weather.windspeed_10m[idx]),
          precipProb: weather.precipitation_probability[idx],
        };
        setData({ snapshot, weather, airQuality, loading: false, error: null });
      })
      .catch((err) => {
        if (!cancelled) setData({ snapshot: null, weather: null, airQuality: null, loading: false, error: String(err) });
      });

    return () => { cancelled = true; };
  }, [city.id]);

  return data;
}
