export function getCityById(id: string): City {
  return CITIES.find((c) => c.id === id) ?? CITIES[0];
}

export function aqiLabel(aqi: number): { label: string; color: string } {
  if (aqi <= 20) return { label: 'Good', color: '#3fb950' };
  if (aqi <= 40) return { label: 'Fair', color: '#d29922' };
  if (aqi <= 60) return { label: 'Moderate', color: '#f0883e' };
  if (aqi <= 80) return { label: 'Poor', color: '#f85149' };
  return { label: 'Very Poor', color: '#8957e5' };
}
